// ─── File: src/test/java/com/bank/hmloop/HashMapCorruptionTest.java ───
package com.bank.hmloop;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class HashMapCorruptionTest {

    // ═══ HashMap: concurrent puts → lost entries ═══
    @Test
    void hashMap_concurrentPuts_loseEntries() throws InterruptedException {
        Map<Integer, Integer> map = new HashMap<>();
        int threads = 20;
        int entriesPerThread = 1000;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            final int base = t * entriesPerThread;
            new Thread(() -> {
                for (int i = 0; i < entriesPerThread; i++) {
                    map.put(base + i, i);
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        int expected = threads * entriesPerThread;
        System.out.println("HashMap: " + map.size() + "/" + expected);
        // Often < 20000! Entries lost due to concurrent structural modification!
    }

    // ═══ ConcurrentHashMap: zero lost entries ═══
    @Test
    void concurrentHashMap_zeroLost() throws InterruptedException {
        ConcurrentHashMap<Integer, Integer> map = new ConcurrentHashMap<>();
        int threads = 20;
        int entriesPerThread = 1000;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            final int base = t * entriesPerThread;
            new Thread(() -> {
                for (int i = 0; i < entriesPerThread; i++) {
                    map.put(base + i, i);
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(map).hasSize(threads * entriesPerThread);  // ALWAYS 20000!
    }

    // ═══ HashMap: get() may return null for existing key ═══
    @Test
    void hashMap_getReturnsNull_forExistingKey() throws InterruptedException {
        Map<String, String> map = new HashMap<>();
        AtomicInteger nullReads = new AtomicInteger(0);
        CountDownLatch done = new CountDownLatch(2);

        // Writer: continuously puts
        new Thread(() -> {
            for (int i = 0; i < 100000; i++) {
                map.put("key-" + (i % 100), "val-" + i);
            }
            done.countDown();
        }).start();

        // Reader: continuously gets
        new Thread(() -> {
            for (int i = 0; i < 100000; i++) {
                if (map.get("key-" + (i % 100)) == null && map.size() > 50) {
                    nullReads.incrementAndGet();  // key exists but get() returns null!
                }
            }
            done.countDown();
        }).start();

        done.await(30, TimeUnit.SECONDS);
        System.out.println("Null reads for existing keys: " + nullReads.get());
        // May be > 0! Corrupted structure returns null for existing data!
    }
}
